"""
permgroup.py -- permutations and the Schreier-Sims algorithm.

Conventions
-----------
A permutation of {0..n-1} is a tuple p with p[i] = image of i.
compose(a, b) = a∘b  (apply b first, then a):  compose(a, b)[i] = a[b[i]].

Group theory used
-----------------
* Orbit-stabilizer / Lagrange:  |G| = |orbit of b| * |Stab_G(b)|
* A stabilizer chain G = G^(0) > G^(1) > ... > G^(k) = 1 where G^(i) fixes the
  first i base points.  Then |G| = prod_i [G^(i) : G^(i+1)] = prod_i |orbit_i|.
* Schreier's lemma: Stab_G(b) is generated by u_{s(y)}^-1 * s * u_y over
  transversal elements u_y and generators s.  This is the engine of the algorithm.
* Coset canonical forms: canon_left(x) picks a unique representative of xH.
"""
from __future__ import annotations

import random
from typing import Iterable, Sequence

Perm = tuple


def identity(n: int) -> Perm:
    return tuple(range(n))


def compose(a: Perm, b: Perm) -> Perm:
    """(a∘b)[i] = a[b[i]]  -- apply b first, then a."""
    return tuple(map(a.__getitem__, b))


def inverse(p: Perm) -> Perm:
    r = [0] * len(p)
    for i, x in enumerate(p):
        r[x] = i
    return tuple(r)


def cycles(p: Perm) -> list[tuple[int, ...]]:
    """Disjoint cycle decomposition (fixed points omitted)."""
    seen, out = [False] * len(p), []
    for i in range(len(p)):
        if not seen[i] and p[i] != i:
            c, j = [], i
            while not seen[j]:
                seen[j] = True
                c.append(j)
                j = p[j]
            out.append(tuple(c))
    return out


def from_cycles(n: int, cyc: Iterable[Sequence[int]]) -> Perm:
    p = list(range(n))
    for c in cyc:
        for a, b in zip(c, list(c[1:]) + [c[0]]):
            p[a] = b
    return tuple(p)


def gcd(a: int, b: int) -> int:
    """Euclid's algorithm."""
    while b:
        a, b = b, a % b
    return a


def perm_order(p: Perm) -> int:
    """Order of p = lcm of its cycle lengths."""
    o = 1
    for c in cycles(p):
        o = o * len(c) // gcd(o, len(c))
    return o


def parity(p: Perm) -> int:
    """0 = even, 1 = odd."""
    return sum(len(c) - 1 for c in cycles(p)) & 1


class StabChain:
    """
    Base and strong generating set (BSGS) built by the deterministic
    Schreier-Sims algorithm.

    Per level i we keep:
      base[i]   the base point b_i
      S[i]      strong generators of G^(i)   (fix b_0..b_{i-1})
      T[i]      transversal  {y: u_y}  with u_y(b_i) = y,  keys = orbit of b_i
      Tinv[i]   the inverses of the transversal elements
    """

    def __init__(self, n: int, gens: Iterable[Perm] = ()):
        self.n = n
        self.id = identity(n)
        self.base: list[int] = []
        self.S: list[list[Perm]] = []
        self.T: list[dict[int, Perm]] = []
        self.Tinv: list[dict[int, Perm]] = []
        self._done: list[set] = []       # Schreier generators already sifted
        self._inv: dict[Perm, Perm] = {}
        for g in dict.fromkeys(gens):
            if g != self.id:
                res, lvl = self._sift(g, 0)
                if res != self.id:
                    self._add_strong(res, lvl)
        self._complete()

    # ---- helpers -------------------------------------------------------
    def _inverse(self, p: Perm) -> Perm:
        q = self._inv.get(p)
        if q is None:
            q = self._inv[p] = inverse(p)
        return q

    def _sift(self, g: Perm, start: int) -> tuple[Perm, int]:
        """Strip g through levels start..; return (residue, level it failed at)."""
        for i in range(start, len(self.base)):
            y = g[self.base[i]]
            u_inv = self.Tinv[i].get(y)
            if u_inv is None:
                return g, i
            g = compose(u_inv, g)          # now g fixes base[i]
        return g, len(self.base)

    def _grow(self, j: int, new_g: Perm) -> None:
        """Extend orbit/transversal at level j after adding generator new_g."""
        Tj, Tij = self.T[j], self.Tinv[j]
        new_inv = self._inverse(new_g)
        queue = []
        for y in list(Tj):
            z = new_g[y]
            if z not in Tj:
                Tj[z] = compose(new_g, Tj[y])
                Tij[z] = compose(Tij[y], new_inv)
                queue.append(z)
        while queue:
            y = queue.pop()
            for s in self.S[j]:
                z = s[y]
                if z not in Tj:
                    Tj[z] = compose(s, Tj[y])
                    Tij[z] = compose(Tij[y], self._inverse(s))
                    queue.append(z)

    def _add_strong(self, g: Perm, lvl: int) -> None:
        if lvl == len(self.base):
            b = next(i for i in range(self.n) if g[i] != i)
            self.base.append(b)
            self.S.append([])
            self.T.append({b: self.id})
            self.Tinv.append({b: self.id})
            self._done.append(set())
        for j in range(lvl + 1):           # g fixes base[:lvl], so g in G^(j), j<=lvl
            self.S[j].append(g)
            self._grow(j, g)

    def _complete(self) -> None:
        """Make sure every Schreier generator sifts to the identity."""
        i = len(self.base) - 1
        while i >= 0:
            found = False
            for s in list(self.S[i]):
                for y in list(self.T[i]):
                    key = (y, s)
                    if key in self._done[i]:
                        continue
                    self._done[i].add(key)
                    h = compose(self.Tinv[i][s[y]], compose(s, self.T[i][y]))
                    res, lvl = self._sift(h, i + 1)
                    if res != self.id:
                        self._add_strong(res, lvl)
                        i = lvl
                        found = True
                        break
                if found:
                    break
            if not found:
                i -= 1

    # ---- public API ----------------------------------------------------
    def order(self) -> int:
        """|G| = product of orbit lengths (Lagrange, applied down the chain)."""
        o = 1
        for t in self.T:
            o *= len(t)
        return o

    def orbit_sizes(self) -> list[int]:
        return [len(t) for t in self.T]

    def contains(self, g: Perm) -> bool:
        if len(g) != self.n:
            return False
        res, _ = self._sift(g, 0)
        return res == self.id

    def random_element(self, rng: random.Random | None = None) -> Perm:
        """Uniformly random group element: u_0 ∘ u_1 ∘ ... with u_i uniform in T[i]."""
        rng = rng or random
        g = self.id
        for t in self.T:
            g = compose(g, t[rng.choice(list(t))])
        return g

    def canon_left(self, x: Perm) -> Perm:
        """
        Canonical representative of the left coset x·H (H = this group).
        At level i choose the orbit point y minimizing x(y) and replace x by x∘u_y.
        Because {h in H_i : h(b_i)=y} = u_y·H_{i+1}, the choice depends only on the
        coset, so every element of x·H yields the same final tuple.
        """
        for i in range(len(self.base)):
            Ti = self.T[i]
            y = min(Ti, key=x.__getitem__)
            x = compose(x, Ti[y])
        return x
